CREATE OR REPLACE FUNCTION public.bix_find_user_by_email(p_email text) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT id FROM auth.users WHERE lower(email) = lower(trim(p_email)) LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.bix_find_user_by_email(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.bix_find_user_by_email(text) TO service_role;